package com.termux.app.workspace;

import android.app.AlertDialog;
import android.content.Context;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;

/** Presentation only: moves existing controls without replacing their validators or callbacks. */
final class AgentLaunchForm {
    private AgentLaunchForm(){}
    static void move(LinearLayout parent,View child){if(child.getParent() instanceof ViewGroup)((ViewGroup)child.getParent()).removeView(child);parent.addView(child,new LinearLayout.LayoutParams(-1,-2));}
    static LinearLayout slot(LinearLayout form,String label,String tag){Context c=form.getContext();TextView title=new TextView(c);title.setText(label);title.setTextSize(11);title.setTextColor(WorkspaceDialogs.MUTED);title.setPadding(0,dp(c,16),0,dp(c,6));form.addView(title);LinearLayout slot=new LinearLayout(c);slot.setOrientation(LinearLayout.VERTICAL);slot.setTag(tag);form.addView(slot,new LinearLayout.LayoutParams(-1,-2));return slot;}
    static LinearLayout details(LinearLayout form,String label,String tag){Context c=form.getContext();TextView toggle=new TextView(c);toggle.setText(label+" ▾");toggle.setTextSize(12);toggle.setTextColor(WorkspaceDialogs.TEXT);toggle.setMinHeight(dp(c,44));toggle.setGravity(Gravity.CENTER_VERTICAL);toggle.setTag(tag+"-toggle");form.addView(toggle);LinearLayout body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setTag(tag);body.setVisibility(View.GONE);form.addView(body,new LinearLayout.LayoutParams(-1,-2));toggle.setOnClickListener(v->{boolean open=body.getVisibility()!=View.VISIBLE;body.setVisibility(open?View.VISIBLE:View.GONE);toggle.setText(label+(open?" ▴":" ▾"));});return body;}
    static void selection(LinearLayout slot,View control){slot.removeAllViews();move(slot,control);if(control instanceof TextView){TextView text=(TextView)control;text.setTextSize(13);text.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);text.setMinHeight(dp(slot.getContext(),44));text.setPadding(dp(slot.getContext(),12),dp(slot.getContext(),10),dp(slot.getContext(),12),dp(slot.getContext(),10));}}
    static void title(AlertDialog dialog,String title){Context c=dialog.getContext();LinearLayout header=new LinearLayout(c);header.setOrientation(LinearLayout.VERTICAL);header.setPadding(dp(c,20),dp(c,10),dp(c,14),dp(c,12));View handle=new View(c);GradientDrawable grip=new GradientDrawable();grip.setColor(WorkspaceDialogs.LINE);grip.setCornerRadius(dp(c,4));handle.setBackground(grip);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(c,32),dp(c,4));hp.gravity=Gravity.CENTER;hp.bottomMargin=dp(c,12);header.addView(handle,hp);LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);TextView name=new TextView(c);name.setText(title);name.setTextSize(16);name.setTypeface(null,android.graphics.Typeface.BOLD);name.setTextColor(WorkspaceDialogs.TEXT);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView close=new TextView(c);close.setText("×");close.setTextSize(24);close.setGravity(Gravity.CENTER);close.setTextColor(WorkspaceDialogs.MUTED);close.setContentDescription(AgentStatusUi.tr(c,"Закрыть","Close"));close.setOnClickListener(v->dialog.cancel());row.addView(close,new LinearLayout.LayoutParams(dp(c,44),dp(c,44)));header.addView(row);dialog.setCustomTitle(header);}
    static void style(AlertDialog dialog){Context c=dialog.getContext();Window w=dialog.getWindow();if(w==null)return;GradientDrawable bg=new GradientDrawable();bg.setColor(WorkspaceDialogs.BG);float r=dp(c,24);bg.setCornerRadii(new float[]{r,r,r,r,0,0,0,0});bg.setStroke(dp(c,1),WorkspaceDialogs.LINE);w.setBackgroundDrawable(bg);w.setGravity(Gravity.BOTTOM);w.setLayout(-1,-2);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);w.getDecorView().setPadding(0,0,0,0);for(int id:new int[]{AlertDialog.BUTTON_NEGATIVE,AlertDialog.BUTTON_POSITIVE}){Button b=dialog.getButton(id);if(b==null)continue;b.setAllCaps(false);b.setTextSize(13);b.setMinHeight(dp(c,46));b.setTextColor(WorkspaceDialogs.TEXT);GradientDrawable shape=new GradientDrawable();shape.setColor(id==AlertDialog.BUTTON_POSITIVE?WorkspaceDialogs.TINT:WorkspaceDialogs.BG);shape.setCornerRadius(dp(c,10));shape.setStroke(dp(c,1),WorkspaceDialogs.LINE);b.setBackground(shape);b.setPadding(dp(c,14),dp(c,8),dp(c,14),dp(c,8));if(b.getLayoutParams() instanceof LinearLayout.LayoutParams){LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)b.getLayoutParams();lp.width=0;lp.weight=1;lp.setMargins(dp(c,4),dp(c,4),dp(c,4),dp(c,8));b.setLayoutParams(lp);}}}
    private static int dp(Context c,int n){return WorkspaceDialogs.dp(c,n);}
}
